<body>
  <main class="app">
    <h1>Todos</h1>
    <p class="subtitle">Stay organized. One task at a time.</p>

    <section class="card" aria-label="Todo application">
      <form id="todo-form" class="input-row">
        <input
          type="text"
          id="todo-input"
          placeholder="What needs to be done?"
          autocomplete="off"
          maxlength="500"
          aria-label="New todo text"
        >
        <button type="submit" id="add-btn">Add</button>
      </form>

      <nav class="filters" aria-label="Filter todos">
        <button class="filter-btn active" data-filter="all">All</button>
        <button class="filter-btn" data-filter="active">Active</button>
        <button class="filter-btn" data-filter="completed">Completed</button>
      </nav>

      <ul id="todo-list" aria-live="polite"></ul>

      <div class="stats">
        <span id="items-left">0 items left</span>
        <button id="clear-completed" type="button">Clear completed</button>
      </div>
