  var STORAGE_KEY = 'todo_a…e_v1';

  /** @type {{id:string,text:string,completed:boolean}[]} */
  var todos = loadTodos();
  var currentFilter = 'all';

  // --- Elements ---
  var form = document.getElementById('todo-form');
  var input = document.getElementById('todo-input');
  var listEl = document.getElementById('todo-list');
  var itemsLeftEl = document.getElementById('items-left');
  var clearBtn = document.getElementById('clear-completed');
  var filterBtns = Array.prototype.slice.call(document.querySelectorAll('.filter-btn'));

  // --- Persistence ---
  function loadTodos() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (t) {
        return t && typeof t.text === 'string' && typeof t.completed === 'boolean';
      });
    } catch (e) {
      return [];
    }
  }

  function saveTodos() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      /* storage unavailable — app still works in-memory */
    }
  }

  // --- Helpers ---
  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function visibleTodos() {
    if (currentFilter === 'active') {
      return todos.filter(function (t) { return !t.completed; });
    }
    if (currentFilter === 'completed') {
      return todos.filter(function (t) { return t.completed; });
    }
    return todos;
  }

  // --- Rendering ---
  function render() {
    listEl.innerHTML = '';
    var items = visibleTodos();

    if (items.length === 0) {
      var empty = document.createElement('li');
      empty.className = 'empty-state';
      empty.textContent =
        currentFilter === 'active' ? 'Nothing active — enjoy!' :
        currentFilter === 'completed' ? 'No completed todos yet.' :
        'No todos yet. Add one above!';
      listEl.appendChild(empty);
    } else {
      items.forEach(function (todo) {
        listEl.appendChild(createTodoElement(todo));
      });
    }

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    itemsLeftEl.textContent = activeCount + (activeCount === 1 ? ' item left' : ' items left');

    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearBtn.style.visibility = hasCompleted ? 'visible' : 'hidden';

    filterBtns.forEach(function (btn) {
      btn.classList.toggle('active', btn.dataset.filter === currentFilter);
    });
  }

  function createTodoElement(todo) {
    var li = document.createElement('li');
    li.className = 'todo-item' + (todo.completed ? ' completed' : '');

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'todo-checkbox';
    checkbox.checked = todo.completed;
    checkbox.setAttribute('aria-label', 'Mark "' + todo.text + '" as ' + (todo.completed ? 'active' : 'completed'));
    checkbox.addEventListener('change', function () {
      toggleTodo(todo.id);
    });

    var span = document.createElement('span');
    span.className = 'todo-text';
    span.textContent = todo.text;
    span.addEventListener('click', function () {
      checkbox.checked = !checkbox.checked;
      toggleTodo(todo.id);
    });

    var delBtn = document.createElement('button');
    delBtn.type = 'button';
    delBtn.className = 'delete-btn';
    delBtn.innerHTML = '&times;';
    delBtn.setAttribute('aria-label', 'Delete "' + todo.text + '"');
    delBtn.addEventListener('click', function () {
      deleteTodo(todo.id);
    });

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(delBtn);
    return li;
  }

  // --- Actions ---
  function addTodo(text) {
    todos.push({ id: generateId(), text: text, completed: false });
    saveTodos();
